{"policy":"permit (
    principal is User,
    action == Action::"authorizePortRequest",
    resource is PortRequest
)
when {
    principal.isPortingSpecialist &&
    (principal != resource.initiatedBy || resource.includesFlaggedOrHighValueLine)
};

forbid (
    principal is User,
    action == Action::"authorizePortRequest",
    resource is PortRequest
)
when {
    (principal.isPortingSpecialist || principal.isPortingSupervisor) &&
    principal == resource.initiatedBy &&
    !resource.includesFlaggedOrHighValueLine
};"}
